import ipaddress

def zone_de(ip, zones):
    adresse = ipaddress.ip_address(ip)
    for nom, cidr in zones.items():
        if adresse in ipaddress.ip_network(cidr):
            return nom
    return "inconnue"

def flux_autorise(matrice, source, destination):
    return source == destination or destination in matrice.get(source, [])

def controler(zones, matrice, essais):
    lignes = []
    for src, dst in essais:
        zs, zd = zone_de(src, zones), zone_de(dst, zones)
        ok = "inconnue" not in (zs, zd) and flux_autorise(matrice, zs, zd)
        lignes.append(src + " (" + zs + ") -> " + dst + " (" + zd + ") : " + ("autorisé" if ok else "bloqué"))
    return lignes
